-- 申论帮 - 示例试卷数据
-- 列名与 schema.sql 一致
-- 注意：JSON 内的中文引号使用 Unicode 形式（\u201c \u201d）避免解析错误

-- 试卷1: 2024年国考申论（省部级）
INSERT INTO papers (pid, source, exam_type, year, season, province, title, material, questions, answer_keys, difficulty, heat, tag, status, created_at) VALUES
('paper_2024_gwy_sbd', '自建', '国考', 2024, '省部级', NULL, '2024年国家公务员录用考试申论（省部级）',
'["基层治理是国家治理的基石。近年来，各地在推进基层治理现代化方面进行了积极探索，但也面临不少挑战。","某社区存在电动自行车上楼充电、楼道堆放杂物等安全隐患，居民多次向物业和社区反映，但问题解决不彻底，反复回潮。社区工作者反映，人手不足、执法权限有限是主要制约因素。","某街道在开展老旧小区改造时，因施工方案与居民需求不匹配，导致居民集体投诉。改造项目涉及管线更新、外立面整治、加装电梯等内容，但前期征求意见不充分，方案设计不够精细。","某乡镇在推进数字政务建设中，投入大量资金建设信息化平台，但建成后使用率不高。基层干部反映，系统操作复杂、数据不互通、维护跟不上等问题突出。"]',
'[{"qid":"q1","type":"归纳概括","stem":"请你根据给定资料，概括当前基层治理中存在的主要问题，并分析原因。","score_max":20,"word_limit":"200-300字","key_points":[{"point":"安全隐患治理不彻底","score":5,"alias":["电动自行车上楼","楼道堆放杂物"]},{"point":"老旧小区改造群众参与不足","score":5,"alias":["征求意见不充分","方案不匹配"]},{"point":"数字政务重建设轻运维","score":5,"alias":["系统使用率低","操作复杂"]},{"point":"基层治理力量薄弱","score":5,"alias":["人手不足","执法权限有限"]}]},{"qid":"q2","type":"对策建议","stem":"针对给定资料反映的问题，请提出推进基层治理现代化的对策建议。","score_max":30,"word_limit":"400-500字","key_points":[{"point":"完善基层治理体制机制","score":6,"alias":["制度建设","顶层设计"]},{"point":"加强基层治理队伍建设","score":6,"alias":["人才培养","充实力量"]},{"point":"推进数字赋能基层治理","score":6,"alias":["信息化","数据共享"]},{"point":"健全群众参与机制","score":6,"alias":["民主协商","共建共治"]},{"point":"强化监督考核","score":6,"alias":["绩效评估","责任落实"]}]}]',
'{"q1":"当前基层治理存在安全隐患治理不彻底、老旧小区改造群众参与不足、数字政务重建设轻运维、基层治理力量薄弱等问题。原因主要包括：基层治理资源不足、群众参与机制不健全、数字化建设缺乏统筹规划。","q2":"一是完善基层治理体制机制，加强顶层设计；二是加强基层治理队伍建设，充实基层力量；三是推进数字赋能基层治理，打破数据壁垒；四是健全群众参与机制，推动共建共治共享；五是强化监督考核，确保政策落地见效。"}',
3, 0, '["基层治理","社区治理"]', 'published', datetime('now'));

-- 试卷2: 2024年省考申论（行政执法）
INSERT INTO papers (pid, source, exam_type, year, season, province, title, material, questions, answer_keys, difficulty, heat, tag, status, created_at) VALUES
('paper_2024_sk_xzzf', '自建', '省考', 2024, NULL, NULL, '2024年各省公务员录用考试申论（行政执法类）',
'["行政执法是政府实施法律法规、管理经济社会事务的重要方式。规范公正文明执法，是建设法治政府的内在要求。","某地城管执法人员在执法过程中存在态度粗暴、程序不规范等问题，引发群众不满和网络舆情。事后调查发现，部分执法人员法律素养不高、培训不到位。","某市在综合行政执法改革后，部门间职责划分不清，导致推诿扯皮现象。群众反映的问题在多个部门之间\u201c转圈\u201d，难以得到及时解决。","部分地区行政执法装备不足，信息化水平较低，执法人员仍依靠纸质文书和手工记录，效率低下且容易出错。"]',
'[{"qid":"q1","type":"归纳概括","stem":"请根据给定资料，分析当前行政执法中存在的突出问题。","score_max":20,"word_limit":"200-300字","key_points":[{"point":"执法行为不规范","score":5,"alias":["态度粗暴","程序不规范"]},{"point":"执法人员素质不高","score":5,"alias":["法律素养低","培训不到位"]},{"point":"部门职责不清","score":5,"alias":["推诿扯皮","职责交叉"]},{"point":"执法信息化水平低","score":5,"alias":["装备不足","效率低下"]}]},{"qid":"q2","type":"对策建议","stem":"请就如何推进规范公正文明执法提出对策建议。","score_max":30,"word_limit":"400-500字","key_points":[{"point":"加强执法人员培训","score":6,"alias":["提升素质","法治教育"]},{"point":"明确部门职责分工","score":6,"alias":["厘清权责","减少推诿"]},{"point":"推进执法信息化建设","score":6,"alias":["数字执法","智能监管"]},{"point":"健全执法监督机制","score":6,"alias":["内部监督","社会监督"]},{"point":"推行柔性执法","score":6,"alias":["首违不罚","教育为主"]}]}]',
'{"q1":"当前行政执法存在执法行为不规范、执法人员素质不高、部门职责不清、执法信息化水平低等突出问题。","q2":"一是加强执法人员培训，提升法治素养和执法能力；二是明确部门职责分工，厘清权责边界；三是推进执法信息化建设，提高执法效率；四是健全执法监督机制，强化内部监督和社会监督；五是推行柔性执法，坚持教育与处罚相结合。"}',
2, 0, '["行政执法","法治政府"]', 'published', datetime('now'));

-- 试卷3: 2023年国考申论（地市级）
INSERT INTO papers (pid, source, exam_type, year, season, province, title, material, questions, answer_keys, difficulty, heat, tag, status, created_at) VALUES
('paper_2023_gwy_dsj', '自建', '国考', 2023, '地市级', NULL, '2023年国家公务员录用考试申论（地市级）',
'["乡村振兴战略是新时代\u201c三农\u201d工作的总抓手。产业兴旺是乡村振兴的重要基础，各地在发展乡村产业方面进行了积极探索。","某村依托当地自然资源，发展特色民宿产业，带动农副产品销售，农民收入显著增加。村里成立了合作社，统一管理、统一经营，形成了品牌效应。","某乡镇引进农产品深加工企业，延长产业链，提高附加值。同时发展农村电商，拓宽销售渠道，解决了农产品\u201c卖难\u201d问题。","某县打造区域公共品牌，统一包装、统一标准、统一推广，提升了农产品市场竞争力。品牌建设带动了当地旅游业发展，实现了三产融合。"]',
'[{"qid":"q1","type":"归纳概括","stem":"请根据给定资料，概括乡村振兴中产业兴旺的主要做法和成效。","score_max":20,"word_limit":"200-300字","key_points":[{"point":"发展特色产业","score":5,"alias":["民宿产业","特色农业"]},{"point":"成立合作组织","score":5,"alias":["合作社","统一经营"]},{"point":"延长产业链","score":5,"alias":["深加工","提高附加值"]},{"point":"拓宽销售渠道","score":5,"alias":["农村电商","品牌建设"]}]},{"qid":"q2","type":"对策建议","stem":"请就如何进一步推动乡村产业振兴提出建议。","score_max":30,"word_limit":"400-500字","key_points":[{"point":"培育特色主导产业","score":6,"alias":["因地制宜","特色发展"]},{"point":"完善利益联结机制","score":6,"alias":["联农带农","共享发展"]},{"point":"加强品牌建设","score":6,"alias":["区域品牌","质量标准"]},{"point":"推进三产融合","score":6,"alias":["农旅融合","产业融合"]},{"point":"强化人才支撑","score":6,"alias":["返乡创业","技能培训"]}]}]',
'{"q1":"主要做法包括：发展特色民宿产业、成立合作社统一经营、引进深加工企业延长产业链、发展农村电商拓宽销路、打造区域公共品牌。成效：农民收入增加、品牌效应显现、三产融合发展。","q2":"一是培育特色主导产业，因地制宜发展优势产业；二是完善利益联结机制，让农民更多分享产业增值收益；三是加强品牌建设，提升农产品市场竞争力；四是推进三产融合，拓展农业多种功能；五是强化人才支撑，吸引各类人才投身乡村产业振兴。"}',
3, 0, '["乡村振兴","产业发展"]', 'published', datetime('now'));

-- 试卷4: 2023年事业单位联考
INSERT INTO papers (pid, source, exam_type, year, season, province, title, material, questions, answer_keys, difficulty, heat, tag, status, created_at) VALUES
('paper_2023_sydw', '自建', '事业单位', 2023, NULL, NULL, '2023年事业单位联考综合应用能力',
'["基层公共服务是保障和改善民生的重要内容。提升基层公共服务水平，是满足人民群众美好生活需要的必然要求。","某社区养老服务中心设施齐全但利用率不高，居民反映服务内容单一、专业人员不足、收费标准不透明等问题。","某地区推进\u201c15分钟服务圈\u201d建设，整合教育、医疗、文化、体育等资源，但部分服务项目尚未真正落地，存在\u201c有圈无服务\u201d的现象。","基层公共服务人才短缺，专业化程度不高。部分地区基层服务人员待遇偏低、职业发展空间有限，难以吸引和留住优秀人才。"]',
'[{"qid":"q1","type":"归纳概括","stem":"请根据给定资料，概括当前基层公共服务存在的主要问题。","score_max":20,"word_limit":"200-300字","key_points":[{"point":"服务内容单一","score":5,"alias":["供需不匹配","服务同质化"]},{"point":"服务设施利用率低","score":5,"alias":["资源闲置","有圈无服务"]},{"point":"专业人才短缺","score":5,"alias":["人员不足","素质不高"]},{"point":"管理机制不健全","score":5,"alias":["收费不透明","标准不统一"]}]},{"qid":"q2","type":"对策建议","stem":"请就如何提升基层公共服务水平提出对策建议。","score_max":30,"word_limit":"400-500字","key_points":[{"point":"丰富服务内容","score":6,"alias":["精准对接需求","多元化服务"]},{"point":"优化资源配置","score":6,"alias":["盘活存量","统筹利用"]},{"point":"加强人才队伍建设","score":6,"alias":["提高待遇","专业培训"]},{"point":"完善管理机制","score":6,"alias":["标准化","规范化"]},{"point":"推进数字化服务","score":6,"alias":["智慧社区","线上服务"]}]}]',
'{"q1":"当前基层公共服务存在服务内容单一、设施利用率低、专业人才短缺、管理机制不健全等问题。","q2":"一是丰富服务内容，精准对接群众需求；二是优化资源配置，盘活存量资源；三是加强人才队伍建设，提高待遇和专业水平；四是完善管理机制，推进标准化规范化；五是推进数字化服务，打造智慧社区。"}',
2, 0, '["公共服务","社区服务"]', 'published', datetime('now'));

-- 试卷5: 2024年国考申论（地市级）
INSERT INTO papers (pid, source, exam_type, year, season, province, title, material, questions, answer_keys, difficulty, heat, tag, status, created_at) VALUES
('paper_2024_gwy_dsj', '自建', '国考', 2024, '地市级', NULL, '2024年国家公务员录用考试申论（地市级）',
'["优化营商环境是推动经济高质量发展的重要举措。各地在深化\u201c放管服\u201d改革、优化营商环境方面进行了积极探索。","某省推行\u201c一网通办\u201d改革，整合各部门政务服务系统，实现企业开办、项目审批等事项网上办理，企业开办时间从原来的5个工作日压缩至1个工作日。","某市建立\u201c企业服务专员\u201d制度，为重点企业提供一对一专属服务。服务专员定期走访企业，收集问题诉求，协调解决实际困难。","某县设立\u201c吐槽窗口\u201d，专门收集企业对政府工作的意见建议。窗口实行\u201c即收即转即办\u201d机制，确保企业诉求件件有回应、事事有着落。"]',
'[{"qid":"q1","type":"归纳概括","stem":"请根据给定资料，概括各地优化营商环境的主要做法。","score_max":20,"word_limit":"200-300字","key_points":[{"point":"推行一网通办改革","score":5,"alias":["网上办理","简化流程"]},{"point":"建立企业服务专员制度","score":5,"alias":["一对一服务","精准帮扶"]},{"point":"设立吐槽窗口收集意见","score":5,"alias":["诉求反馈","即收即办"]},{"point":"压缩办事时限","score":5,"alias":["提高效率","压缩时间"]}]},{"qid":"q2","type":"对策建议","stem":"请就如何进一步优化营商环境提出对策建议。","score_max":30,"word_limit":"400-500字","key_points":[{"point":"深化数字政务改革","score":6,"alias":["数据共享","智慧政务"]},{"point":"完善企业服务体系","score":6,"alias":["全生命周期","精准服务"]},{"point":"强化法治保障","score":6,"alias":["产权保护","公平竞争"]},{"point":"降低制度性交易成本","score":6,"alias":["减税降费","简政放权"]},{"point":"建立常态化沟通机制","score":6,"alias":["政企沟通","诉求响应"]}]}]',
'{"q1":"主要做法包括：推行一网通办改革实现网上办理、建立企业服务专员制度提供一对一服务、设立吐槽窗口收集企业意见建议、压缩办事时限提高效率。","q2":"一是深化数字政务改革，推动数据共享和智慧政务建设；二是完善企业服务体系，提供全生命周期精准服务；三是强化法治保障，保护产权和公平竞争；四是降低制度性交易成本，持续推进减税降费和简政放权；五是建立常态化政企沟通机制，及时响应企业诉求。"}',
3, 0, '["营商环境","放管服改革"]', 'published', datetime('now'));

-- 试卷6: 2023年省考申论
INSERT INTO papers (pid, source, exam_type, year, season, province, title, material, questions, answer_keys, difficulty, heat, tag, status, created_at) VALUES
('paper_2023_sk', '自建', '省考', 2023, NULL, '浙江', '2023年浙江省公务员录用考试申论',
'["数字经济发展是浙江省的\u201c一号工程\u201d。近年来，浙江在推进数字经济创新发展方面取得了显著成效。","某市建设\u201c城市大脑\u201d，整合交通、医疗、教育、城管等数据资源，实现城市治理的智能化、精细化。交通拥堵指数下降15%，市民办事等候时间缩短60%。","某县发展农村电商，建成电商产业园和直播基地，培训农民成为\u201c新农人\u201d。当地特色农产品通过直播带货销往全国，带动农民增收致富。","某区推进制造业数字化改造，建设\u201c未来工厂\u201d，实现生产效率提升30%、能耗降低20%。同时培育了一批数字化服务商，为中小企业提供改造方案。"]',
'[{"qid":"q1","type":"归纳概括","stem":"请根据给定资料，概括浙江省推进数字经济发展的主要做法和成效。","score_max":20,"word_limit":"200-300字","key_points":[{"point":"建设城市大脑推进智慧治理","score":5,"alias":["数据整合","智能化治理"]},{"point":"发展农村电商助农增收","score":5,"alias":["直播带货","新农人培训"]},{"point":"推进制造业数字化改造","score":5,"alias":["未来工厂","智能制造"]},{"point":"培育数字化服务商","score":5,"alias":["产业生态","服务赋能"]}]},{"qid":"q2","type":"对策建议","stem":"请就如何进一步推动数字经济高质量发展提出建议。","score_max":30,"word_limit":"400-500字","key_points":[{"point":"加强数字基础设施建设","score":6,"alias":["5G网络","数据中心"]},{"point":"推进数据要素市场化","score":6,"alias":["数据交易","数据开放"]},{"point":"培育数字经济新业态","score":6,"alias":["平台经济","共享经济"]},{"point":"强化数字人才培养","score":6,"alias":["产教融合","技能提升"]},{"point":"完善数字治理体系","score":6,"alias":["数据安全","隐私保护"]}]}]',
'{"q1":"主要做法包括：建设城市大脑推进智慧治理、发展农村电商助农增收、推进制造业数字化改造、培育数字化服务商。成效包括：治理效率提升、农民收入增加、生产效率提高。","q2":"一是加强数字基础设施建设，夯实发展底座；二是推进数据要素市场化，释放数据价值；三是培育数字经济新业态，拓展发展空间；四是强化数字人才培养，提供智力支撑；五是完善数字治理体系，保障数据安全。"}',
3, 0, '["数字经济","创新发展"]', 'published', datetime('now'));
